# thresholds learned from 1,200 labelled invoices, per field
THRESH = {"vendor_name": 0.70, "invoice_date": 0.85, "total": 0.95}

def route(doc):
    if doc.validation_errors or doc.stated_total != sum(doc.lines):
        return "review", "validation"
    low = [f for f, c in doc.confidence.items() if c < THRESH[f]]
    if low:
        return "review", low          # only these fields shown to reviewer
    if sampler.pick(stratum=(doc.doc_type, doc.vendor_tier), rate=0.03):
        return "review", "audit_sample"
    return "accept", None

